/**
 * EPL 실선수 스냅샷 — 팀당 30~34인(유망주 포함), 2025-26 시즌 + 2026 여름
 * 이적 기준 (data-sourcing.md §4 MVP 레시피). 멀티에이전트 워크플로우로
 * WebSearch 교차검증하며 생성·적대적 검증·팀 간 중복 해소했다.
 *
 * ⚠️ 라이선스 부채 (data-sourcing.md §7): 능력치·실명은 EA IP·NIL 대상.
 * MVP 한정 사용 — 정식 출시 전 자체 산정 능력치·가명 전환으로 청산한다.
 *
 * 세계관 주의: 인게임 연도는 가상으로 진행되고, 유스 유입은 계속 합성
 * 가명으로 생성한다 (실존 유소년에게 가상 서사를 입히는 리스크 회피,
 * narrative.md §7). 강등 팀(레스터·입스위치·사우샘프턴)은 카탈로그 유지를
 * 위해 실제 2025-26 스쿼드로 채운다.
 */
export interface RealPlayerSeed {
  /** 로마자 통용 표기 — id 슬러그·외부 데이터 매핑용 */
  nameEn: string;
  /** 한국 축구 언론 통용 한글 표기 — 게임 내 표시명 */
  nameKo: string;
  /** 출생년월일 (YYYY-MM-DD) — 나이는 플레이 날짜 기준 계산 */
  birthdate: string;
  position: string;
  positionGroup: PositionGroup;
  pace: number;
  shooting: number;
  passing: number;
  dribbling: number;
  defending: number;
  physical: number;
  /** GK 전용 — 종합 overall 수준 */
  goalkeeping?: number;
  potential: number;
}

